90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OID: u8 = 0x06;
111	    const TAG_SEQUENCE: u8 = 0x30;
112	    const TAG_SET: u8 = 0x31;
113	    const TAG_UTC_TIME: u8 = 0x17;
114	    const TAG_GENERALIZED_TIME: u8 = 0x18;
115	
116	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
117	    /// length encodings and truncated data.
118	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
119	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
120	        if tag & 0x1F == 0x1F {
121	            return Err("multi-byte tags are not supported".to_string());
122	        }
123	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
124	        let (len, header_len) = match first_len {
125	            0x00..=0x7F => (first_len as usize, 2),
126	            0x80 => return Err("indefinite length is not valid DER".to_string()),
127	            0xFF => return Err("reserved length byte".to_string()),
128	            long => {
129	                let n = (long & 0x7F) as usize;
130	                if !(1..=4).contains(&n) {
131	                    return Err("length is too large".to_string());
132	                }
133	                let bytes = buf
134	                    .get(2..2 + n)
135	                    .ok_or_else(|| "truncated long length".to_string())?;
136	                if bytes[0] == 0 {
137	                    return Err("non-minimal length encoding".to_string());
138	                }
139	                let mut len = 0usize;
140	                for &b in bytes {
141	                    len = len
142	                        .checked_shl(8)
143	                        .and_then(|l| l.checked_add(b as usize))
144	                        .ok_or_else(|| "length overflow".to_string())?;
145	                }
146	                if len < 0x80 {
147	                    return Err("non-minimal length encoding".to_string());
148	                }
149	                (len, 2 + n)
150	            }
151	        };
152	        let total = header_len
153	            .checked_add(len)
154	            .filter(|&t| t <= buf.len())
155	            .ok_or_else(|| "truncated TLV content".to_string())?;
156	        Ok((
157	            Tlv {
158	                tag,
159	                content: &buf[header_len..total],
160	            },
161	            &buf[total..],
162	        ))
163	    }
164	
165	    fn read_tagged<'a>(
166	        buf: &'a [u8],
167	        tag: u8,
168	        what: &str,
169	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
170	        let (tlv, rest) = read_tlv(buf)?;
171	        if tlv.tag != tag {
172	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
173	        }
174	        Ok((tlv, rest))
175	    }
176	
177	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
178	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
179	        // signatureValue BIT STRING } — and nothing trailing.
180	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
181	        if !rest.is_empty() {
182	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
183	        }
184	
185	        let c = cert.content;
186	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
187	        let (_sig_alg, c) = read_tagged(c, TAG_SEQUENCE, "signatureAlgorithm")?;
188	        let (sig_value, c) = read_tlv(c)?;
189	        if sig_value.tag != TAG_BIT_STRING {
190	            return Err("signature must be a BIT STRING".to_string());
191	        }
192	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
193	            return Err("invalid signature BIT STRING".to_string());
194	        }
195	        if !c.is_empty() {
196	            return Err("trailing data in Certificate".to_string());
197	        }
198	
199	        // TBSCertificate ::= SEQUENCE {
200	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
201	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
202	        let t = tbs.content;
203	        let (first, t2) = read_tlv(t)?;
204	        let t = if first.tag == 0xA0 {
205	            let (version, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
206	            if !vrest.is_empty() || version.content.len() != 1 || version.content[0] > 2 {
207	                return Err("invalid certificate version".to_string());
208	            }
209	            t2
210	        } else {
211	            t // No explicit version: v1 certificate.
212	        };
213	
214	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
215	        let t = t3;
216	        let (_tbs_sig, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
217	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
218	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
219	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
220	        let (_spki, mut t) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
221	        // Remaining fields (issuerUniqueID, subjectUniqueID, extensions, ...)
222	        // are optional; they must still each be well-formed TLVs.
223	        while !t.is_empty() {
224	            let (_, rest) = read_tlv(t)?;
225	            t = rest;
226	        }
227	
228	        let serial_hex = format_serial(serial.content)?;
229	        let issuer = format_name(issuer)?;
230	        let subject = format_name(subject)?;
231	
232	        let v = validity.content;
233	        let (nb, v2) = read_tlv(v)?;
234	        let (na, v3) = read_tlv(v2)?;
235	        if !v3.is_empty() {
236	            return Err("trailing data in validity".to_string());
237	        }
238	        let not_before = format_time(nb)?;
239	        let not_after = format_time(na)?;
240	
241	        Ok(Cert {
242	            subject,
243	            issuer,
244	            serial_hex,
245	            not_before,
246	            not_after,
247	        })
248	    }
249	
250	    /// Render the serial number as upper-case hex, matching the integer value
251	    /// (a DER sign-padding 0x00 byte is not part of the number).
252	    fn format_serial(content: &[u8]) -> Result<String, String> {
253	        if content.is_empty() {
254	            return Err("empty serial number".to_string());
255	        }
256	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
257	            return Err("non-minimal serial number encoding".to_string());
258	        }
259	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
260	            return Err("non-minimal serial number encoding".to_string());
261	        }
262	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
263	            return Err("negative serial number".to_string());
264	        }
265	        let digits = if content.len() > 1 && content[0] == 0x00 {
266	            &content[1..]
267	        } else {
268	            content
269	        };
270	        let mut s = String::with_capacity(digits.len() * 2);
271	        for b in digits {
272	            write!(s, "{b:02X}").unwrap();
273	        }
274	        if s.is_empty() {
275	            s.push_str("00");
276	        }
277	        Ok(s)
278	    }
279	
280	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
281	    /// multi-valued RDNs joined with '+'). Values of known attribute types
282	    /// are emitted as real UTF-8 text so non-ASCII content is preserved
283	    /// verbatim; attributes without a known short name use their dotted OID
284	    /// and the '#' form carrying the value's full DER encoding in hex.
285	    fn format_name(name: Tlv) -> Result<String, String> {
286	        let mut rdn_buf = name.content;
287	        let mut rdns: Vec<String> = Vec::new();
288	        while !rdn_buf.is_empty() {
289	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
290	            rdn_buf = rest;
291	
292	            let mut atv_buf = set.content;
293	            let mut parts = Vec::new();
294	            while !atv_buf.is_empty() {
295	                let (atv, rest) =
296	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
297	                atv_buf = rest;
298	
299	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
300	                let (value, after_value) = read_tlv(after_oid)?;
301	                if !after_value.is_empty() {
302	                    return Err("trailing data in attribute value".to_string());
303	                }
304	
305	                let oid_arcs = parse_oid(oid.content)?;
306	                match oid_short_name(&oid_arcs) {
307	                    Some(label) => {
308	                        let text = decode_attribute_value(value.tag, value.content)?;
309	                        parts.push(format!("{label}={}", escape_value(&text)));
310	                    }
311	                    None => {
312	                        // Unknown attribute type: RFC 4514 requires the form
313	                        // OID=#hex, where the hex is the full DER encoding
314	                        // (tag, length and content) of the attribute value.
315	                        // The value is still validated: a UTF8String must
316	                        // hold valid UTF-8 even when shown as hex.
317	                        if value.tag == 0x0C {
318	                            std::str::from_utf8(value.content)
319	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
320	                        }
321	                        let tlv_len = after_oid.len() - after_value.len();
322	                        let tlv_bytes = &after_oid[..tlv_len];
323	                        let mut hex = String::with_capacity(tlv_bytes.len() * 2);
324	                        for b in tlv_bytes {
325	                            write!(hex, "{b:02X}").unwrap();
326	                        }
327	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
328	                    }
329	                }
330	            }
331	            if parts.is_empty() {
332	                return Err("empty RelativeDistinguishedName".to_string());
333	            }
334	            rdns.push(parts.join("+"));
335	        }
336	        rdns.reverse();
337	        Ok(rdns.join(","))
338	    }
339	
340	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
341	        if content.is_empty() {
342	            return Err("empty OID".to_string());
343	        }
344	        let mut arcs = Vec::new();
345	        // The first subidentifier encodes the first two arcs as
346	        // 40*first + second and is itself a base-128 quantity, so it can
347	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
348	        let mut i = 0;
349	        let first = read_oid_arc(content, &mut i)?;
350	        match first {
351	            0..=39 => {
352	                arcs.push(0);
353	                arcs.push(first);
354	            }
355	            40..=79 => {
356	                arcs.push(1);
357	                arcs.push(first - 40);
358	            }
359	            _ => {
360	                arcs.push(2);
361	                arcs.push(first - 80);
362	            }
363	        }
364	        while i < content.len() {
365	            arcs.push(read_oid_arc(content, &mut i)?);
366	        }
367	        Ok(arcs)
368	    }
369	
370	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
371	    /// continuation bytes and non-minimal encodings.
372	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
373	        let start = *i;
374	        let mut value = 0u64;
375	        loop {
376	            let b = *content
377	                .get(*i)
378	                .ok_or_else(|| "truncated OID arc".to_string())?;
379	            value = value
380	                .checked_mul(128)
381	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
382	                .ok_or_else(|| "OID arc overflow".to_string())?;
383	            *i += 1;
384	            if b & 0x80 == 0 {
385	                break;
386	            }
387	        }
388	        if *i - start > 1 && content[start] == 0x80 {
389	            return Err("non-minimal OID arc encoding".to_string());
390	        }
391	        Ok(value)
392	    }
393	
394	    fn arcs_to_string(arcs: &[u64]) -> String {
395	        arcs.iter()
396	            .map(u64::to_string)
397	            .collect::<Vec<_>>()
398	            .join(".")
399	    }
400	
401	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
402	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
403	        let name = match arcs {
404	            [2, 5, 4, 3] => "CN",
405	            [2, 5, 4, 4] => "SN",
406	            [2, 5, 4, 5] => "serialNumber",
407	            [2, 5, 4, 6] => "C",
408	            [2, 5, 4, 7] => "L",
409	            [2, 5, 4, 8] => "ST",
410	            [2, 5, 4, 9] => "STREET",
411	            [2, 5, 4, 10] => "O",
412	            [2, 5, 4, 11] => "OU",
413	            [2, 5, 4, 12] => "title",
414	            [2, 5, 4, 17] => "postalAddress",
415	            [2, 5, 4, 18] => "postalCode",
416	            [2, 5, 4, 20] => "telephoneNumber",
417	            [2, 5, 4, 42] => "givenName",
418	            [2, 5, 4, 43] => "initials",
419	            [2, 5, 4, 44] => "generationQualifier",
420	            [2, 5, 4, 46] => "dnQualifier",
421	            [2, 5, 4, 65] => "pseudonym",
422	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
423	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
424	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
425	            _ => return None,
426	        };
427	        Some(name)
428	    }
429	
430	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
431	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
432	        let s = match tag {
433	            0x0C => std::str::from_utf8(content)
434	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
435	                .to_string(),
436	            // ASCII-family strings: every byte is also its Unicode code point.
437	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
438	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
439	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
440	            0x1E => {
441	                if content.len() % 2 != 0 {
442	                    return Err("odd-length BMPString".to_string());
443	                }
444	                let units: Vec<u16> = content
445	                    .chunks_exact(2)
446	                    .map(|c| u16::from_be_bytes([c[0], c[1]]))
447	                    .collect();
448	                char::decode_utf16(units.iter().copied())
449	                    .map(|r| r.map_err(|_| "unpaired surrogate in BMPString".to_string()))
450	                    .collect::<Result<String, _>>()?
451	            }
452	            0x1C => {
453	                if content.len() % 4 != 0 {
454	                    return Err("invalid UniversalString length".to_string());
455	                }
456	                let mut s = String::new();
457	                for c in content.chunks_exact(4) {
458	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
459	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
460	                        return Err("invalid code point in UniversalString".to_string());
461	                    }
462	                    s.push(char::from_u32(cp).unwrap());
463	                }
464	                s
465	            }
466	            _ => {
467	                return Err(format!(
468	                    "unsupported attribute value string type (tag 0x{tag:02X})"
469	                ))
470	            }
471	        };
472	        Ok(s)
473	    }
474	
475	    /// RFC 4514 value escaping; everything above the ASCII control range
476	    /// (including CJK text) passes through unchanged.
477	    fn escape_value(value: &str) -> String {
478	        let mut out = String::with_capacity(value.len());
479	        let last = value.chars().count().saturating_sub(1);
480	        for (i, c) in value.chars().enumerate() {
481	            let at_edge = i == 0 || i == last;
482	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
483	                || (at_edge && (c == ' ' || c == '#'));
484	            if needs_backslash {
485	                out.push('\\');
486	                out.push(c);
487	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
488	                let mut buf = [0u8; 4];
489	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
490	                write!(out, "\\{b:02X}").unwrap();
491	            } else {
492	                out.push(c);
493	            }
494	        }
495	        out
496	    }
497	
498	    fn format_time(tlv: Tlv) -> Result<String, String> {
499	        let (y, mo, d, h, mi, se) = match tlv.tag {
500	            TAG_UTC_TIME => {
501	                let c = tlv.content;
502	                if c.len() != 13 || c[12] != b'Z' {
503	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
504	                }
505	                let digits = &c[..12];
506	                if !digits.iter().all(|b| b.is_ascii_digit()) {
507	                    return Err("non-numeric UTCTime".to_string());
508	                }
509	                let n = |a: usize, b: usize| -> u32 {
510	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
511	                };
512	                let yy = n(0, 1);
513	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
514	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
515	            }
516	            TAG_GENERALIZED_TIME => {
517	                let c = tlv.content;
518	                if c.len() != 15 || c[14] != b'Z' {
519	                    return Err(
520	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
521	                    );
522	                }
523	                let digits = &c[..14];
524	                if !digits.iter().all(|b| b.is_ascii_digit()) {
525	                    return Err("non-numeric GeneralizedTime".to_string());
526	                }
527	                let n = |a: usize, b: usize| -> u32 {
528	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
529	                };
530	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
531	            }
532	            other => return Err(format!("invalid time tag 0x{other:02X}")),
533	        };
534	        validate_datetime(y, mo, d, h, mi, se)?;
535	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
536	    }
537	
538	    fn validate_datetime(
539	        year: i32,
540	        month: u32,
541	        day: u32,
542	        hour: u32,
543	        minute: u32,
544	        second: u32,
545	    ) -> Result<(), String> {
546	        if !(1..=12).contains(&month) {
547	            return Err("invalid month in certificate time".to_string());
548	        }
549	        if hour > 23 || minute > 59 || second > 59 {
550	            return Err("invalid time of day in certificate time".to_string());
551	        }
